import type { MenuProps } from "./menu.types";
import type { CSSObject } from "@emotion/react";
import type { ComponentStyleVariantConfig, Theme } from "@types";

import styled from "@emotion/styled";
import { getExcludedDOMProps, getStyleSlots } from "@system";
import { useMemo } from "react";

// Make sure component name matches its type in the ThemeComponentVariants
const componentName = "Menu";

// Generate child element class names for the component, should match available style slots
export const MenuClasses = {
  root: "exp-textura_menu",
  group: "exp-textura_menu_group",
  groupLabel: "exp-textura_menu_group_label",
  trigger: "exp-textura_menu_trigger",
  content: "exp-textura_menu_content",
  divider: "exp-textura_menu_divider",
  subContent: "exp-textura_menu_sub_content",
};

// Set up style variant settings for the component (if more than "default"), using style slots
const getVariantConfig = (theme: Theme): ComponentStyleVariantConfig => ({
  "icons-only": {
    content: { minWidth: "max-content", padding: theme.toRem(theme.spacing[4]) },
    group: { padding: 0 },
  },
});

const generateStyles = (props: MenuProps): CSSObject => {
  const { currentTheme: theme, variant, styleSlots: styleSlotsProp } = props;
  if (!theme) return {};

  // We are within an Emotion styled component, so we can utilize hooks
  // eslint-disable-next-line react-hooks/rules-of-hooks
  const styleSlots = useMemo(
    () =>
      getStyleSlots<MenuProps["styleSlots"]>(
        componentName,
        theme,
        variant,
        styleSlotsProp,
        getVariantConfig(theme),
      ),
    [theme, variant, styleSlotsProp],
  );

  // Return the JSS generated from the variant settings, make sure to include style slots
  return {
    all: "unset",
    boxSizing: "border-box",

    [`.${MenuClasses.content}`]: {
      margin: 0,
      listStyle: "none",
      overflowY: "auto",
      width: "max-content",
      maxHeight: "var(--radix-popper-available-height, 100vh)",
      backgroundColor: theme.color.background.default,
      border: `${theme.toRem(theme.border.width.sm)} solid ${theme.color.border.default}`,
      borderRadius: theme.toRem(theme.border.radius.sm),
      boxShadow: theme.dropShadow.lg,
      color: theme.color.content.default,
      ...theme.typography.body.md,
      minWidth: theme.toRem(260),
      zIndex: theme.zIndex.dynamic,
      "&:focus-visible": {
        boxShadow: theme.dropShadow.lg,
      },
      ...styleSlots?.content,
    },

    [` .${MenuClasses.trigger}`]: {
      cursor: "pointer",
      "&[data-state=open]": {
        ...styleSlots?.triggerOpen,
      },
      ...styleSlots?.trigger,
    },

    [`.${MenuClasses.divider}`]: {
      height: theme.toRem(theme.border.width.sm),
      backgroundColor: theme.color.border.default,
      ...styleSlots?.divider,
    },

    [`.${MenuClasses.groupLabel}`]: {
      display: "flex",
      alignItems: "baseline",
      color: theme.color.content.default,
      padding: `${theme.toRem(theme.spacing[8])} ${theme.toRem(theme.spacing[8])} 0 ${theme.toRem(theme.spacing[8])}`,
      ...theme.typography.label.sm,
      ...styleSlots?.groupLabel,
    },

    [`.${MenuClasses.group}`]: {
      display: "flex",
      flexDirection: "column",
      gap: theme.toRem(theme.spacing[4]),
      padding: theme.toRem(theme.spacing[8]),
      ...styleSlots?.group,
    },

    [`.${MenuClasses.subContent}`]: {
      zIndex: theme.zIndex.dynamic,
      ...styleSlots?.subContent,
    },

    ...styleSlots?.root,
  };
};

// Certain props passed to styled components should not be passed to the DOM element
const excludedDOMProps = getExcludedDOMProps();

// Define the styled component, exclude props from the DOM, generate themed JSS
export const StyledMenu = styled("div", {
  shouldForwardProp: (prop) => !excludedDOMProps.includes(prop),
})<MenuProps>((props) => generateStyles(props));

export const StyledMenuContent = styled("div", {
  shouldForwardProp: (prop) => !excludedDOMProps.includes(prop),
})<MenuProps>((props) => generateStyles(props));
